-- Migration PermitRegistry 1.0.0 -> 1.1.0 (change request CR-7).
-- HAND-WRITTEN from `dmtool.py diff` output; review before running. Not regenerated by dmtool.
-- All steps are additive: no column is renamed, retyped, dropped or made NOT NULL,
-- so existing rows (about 2 million permits) stay valid and existing queries keep working.
-- ADD COLUMN without a default is a catalog-only change in PostgreSQL (no table rewrite).

BEGIN;

-- CR-7 item 5: condition categories (extensible code list, maintained by the permits team; D-008)
CREATE TABLE permit_registry.condition_category (
  code text PRIMARY KEY,
  label text,
  description text,
  deprecated boolean NOT NULL DEFAULT false
);
INSERT INTO permit_registry.condition_category (code, description) VALUES
  ('environmental', 'Condition protecting the environment.'),
  ('safety',        'Condition concerning the safety of people or property.'),
  ('other',         'Any other condition.');
COMMENT ON TABLE permit_registry.condition_category IS 'Category of a permit condition.';

ALTER TABLE permit_registry.permit_condition ADD COLUMN category text;
ALTER TABLE permit_registry.permit_condition
  ADD FOREIGN KEY (category) REFERENCES permit_registry.condition_category (code);
COMMENT ON COLUMN permit_registry.permit_condition.category IS 'Category of the condition. Expected for new conditions; empty for conditions recorded before 1.1.0 until they are classified.';

-- CR-7 item 4: validity end with time of day (new column; valid_until is deprecated but kept; D-007)
ALTER TABLE permit_registry.permit ADD COLUMN valid_until_date_time timestamptz;
COMMENT ON COLUMN permit_registry.permit.valid_until_date_time IS 'Exact end of validity with time of day and UTC offset (e.g. 2027-03-31T12:00:00+02:00). The permit is valid up to, but not including, this instant.';
COMMENT ON COLUMN permit_registry.permit.valid_until IS 'Last day of validity (date only). Still populated for 1.0.0 consumers; must equal the local calendar date of validUntilDateTime when both are present (C-003).';
-- No backfill: for existing permits only the date is known (see open question Q-005).

-- CR-7 item 2: applicant (optional/voidable for now; required for new permits by rule C-002; D-005)
ALTER TABLE permit_registry.permit
  ADD COLUMN applicant_name varchar(200),
  ADD COLUMN applicant_organisation varchar(200),
  ADD COLUMN applicant_address_street varchar(200),
  ADD COLUMN applicant_address_postal_code varchar(10),
  ADD COLUMN applicant_address_city varchar(100);
-- Keep the applicant structurally complete when present (name, postal code and city are
-- mandatory inside Applicant). NOT VALID + VALIDATE avoids a long lock on the big table;
-- the columns are new, so validation cannot fail.
ALTER TABLE permit_registry.permit ADD CONSTRAINT permit_applicant_complete CHECK (
  (applicant_name IS NULL AND applicant_organisation IS NULL AND applicant_address_street IS NULL
     AND applicant_address_postal_code IS NULL AND applicant_address_city IS NULL)
  OR (applicant_name IS NOT NULL AND applicant_address_postal_code IS NOT NULL AND applicant_address_city IS NOT NULL)
) NOT VALID;
ALTER TABLE permit_registry.permit VALIDATE CONSTRAINT permit_applicant_complete;
COMMENT ON COLUMN permit_registry.permit.applicant_name IS 'Name of the applicant (natural person or contact person).';
COMMENT ON COLUMN permit_registry.permit.applicant_organisation IS 'Organisation the applicant acts for, if any.';

-- CR-7 item 1 (file number): documentation only, column stays "reference" (D-004)
COMMENT ON COLUMN permit_registry.permit.reference IS 'File number under which the authority handles the permit (business term "file number"; the technical/exchange name stays "reference", see D-004).';

-- CR-7 item 6 (keywords): deprecated, table kept until the next major release (D-009)
COMMENT ON TABLE permit_registry.permit_keywords IS 'DEPRECATED since 1.1.0 - Free keywords. No longer used; producers should stop populating it.';

-- permit_history stores row_data as jsonb, so new columns need no change there.
-- Applicant data is personal data: review grants on permit and permit_history (Q-004).

COMMIT;
